  /// `{주제}` 같은 플레이스홀더를 [values]로 바꾼다.
  /// 값에 없는 플레이스홀더는 그대로 둔다.
  static String fill(String template, Map<String, String> values) {
    var result = template;
    values.forEach((name, value) {
      result = result.replaceAll('{$name}', value);
    });
    return result;
  }
}
